INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷召陈懋随军征漠北", "description": "朝廷召宁阳侯陈懋随军征讨漠北。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年正月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2c6936ac-32b4-5657-9208-05a3483dc737"}, {"title": "朱高炽代行南郊祭祀", "description": "皇太子朱高炽在南郊代行祭祀天地的大礼。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年正月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "191fe41c-194f-5501-b812-4bc833a73d3a"}, {"title": "明廷免多地水灾田租并赎回被卖子女", "description": "朝廷免去扬州、淮安、凤阳、陈州因上年水灾所涉田租，并赎回军民卖出的子女。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年正月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "55871ff0-7bfc-5968-a21e-498a5d4e3bc6"}, {"title": "明廷因北征诏告天下", "description": "朱棣将北征一事诏告天下。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年二月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "454cb752-2ffa-516d-8ed3-acf7d1ef5bdf"}, {"title": "夏原吉辅导皇长孙，仍兼理行在的吏部、户部和兵部事务", "description": "永乐8年（年号对照1410年）二月，夏原吉辅导皇长孙，仍兼理行在的吏部、户部和兵部事务。", "start_year": 1410, "end_year": 1410, "time_original": "永乐8年（年号对照1410年）二月；公元年核为1410年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "1a55b513-e738-5ad2-8f8d-ff631be9a600"}, {"title": "朱高炽复查囚案并获准减免部分罪犯", "description": "皇太子朱高炽复查囚犯案件，奏请宽免杂犯死罪及以下者，获朝廷批准。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年二月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3bac55cb-80d8-5f3f-a50a-246c95303cb7"}, {"title": "朱棣离开北京北征", "description": "朱棣于二月丁未从北京启程北征。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年二月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b891d6b7-0e86-572e-8bf9-8627ae123894"}, {"title": "明廷派人祭祀北征途中名山大川", "description": "朝廷派人祭祀北征途中经过的名山大川。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年二月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9723e53b-b6e1-5be7-9702-04c051964064"}, {"title": "北征军举行检阅", "description": "本纪记载，北征军于二月乙丑举行大规模检阅。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年二月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8f81fb86-be84-542a-93d4-b0b8066f5f11"}, {"title": "明廷明确北征各部统军将领", "description": "王友统率中军，柳升任其副手。何福、郑亨分领左右哨，陈懋、刘才分领左右掖，刘江统率前哨。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年三月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7e2b9b2d-0bf4-5691-aa85-ac28ad8ea3f6"}, {"title": "北征军进抵鸣銮戍", "description": "本纪记载，北征军在三月甲戌抵达鸣銮戍。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年三月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "246d6c21-d55b-55fa-a483-4602ae976f3a"}, {"title": "北征军在出战前誓师", "description": "本纪记载，北征军在三月乙亥誓师。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年三月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b379adbd-f658-59f4-9adf-08990fbea1ff"}, {"title": "朱棣驻威虏镇并给卫士发水", "description": "朱棣驻威虏镇，把骆驼驮来的水分发给卫士，看到军士都已进食才自己用膳。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年四月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d3f0679d-5d3d-548c-a922-82b83765454f"}, {"title": "明廷将胪朐河更名饮马河", "description": "明军北征经过胪朐河，将它更名为饮马河。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年五月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dcd8c926-92c5-58c1-bb21-31c9d173b29a"}, {"title": "明军渡饮马河追击本雅失里", "description": "明军得知本雅失里向西逃走，渡过饮马河追击。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年五月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f4f7694f-10e4-5453-ae21-692d591006cc"}, {"title": "明军在斡难河击败本雅失里", "description": "明军追至斡难河并击败本雅失里。本纪称本雅失里和七名骑兵逃走。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年五月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "917a82af-8e89-5c0e-9b07-96f428d14903"}, {"title": "明军返驻饮马河并改征阿鲁台", "description": "明军返回饮马河驻扎，朱棣下诏调军征讨阿鲁台。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年五月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dbda556b-c39b-53b0-8296-c6136c0c0237"}, {"title": "肃州卫发生变乱，朱迪等出兵平定", "description": "哈剌马牙杀死都指挥刘秉谦，控制肃州卫并起兵反明，千户朱迪等平定此事。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年五月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2d0eb673-83d6-5313-a047-f699f1f3b8cf"}, {"title": "朱棣率军击败阿鲁台", "description": "本纪称阿鲁台假意归降，随后率部来攻。朱棣率骑兵迎击并取胜，本纪记明军追出一百多里。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年六月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f67a923e-fd27-5efd-a000-d029067edf3d"}, {"title": "明军再次击败阿鲁台所部", "description": "本纪记载，明军于六月丁未再次击败阿鲁台所部。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年六月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8915e46c-63fb-5883-bca6-b73e03b10c44"}, {"title": "北征军班师", "description": "本纪记载，北征军于六月己酉班师。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年六月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0acf5af3-1543-5e39-a807-d0500bac4426"}, {"title": "北征军返回途中驻于开平", "description": "本纪记载，北征军于七月丁卯抵达开平。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年七月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a71694cc-ebd9-579d-ab10-439936db6191"}, {"title": "朱棣在开平赐宴后恢复常膳", "description": "本纪记载，朱棣在军中念及士卒艰苦，常吃蔬食。到开平赐宴赏赐，到这一天才恢复平日膳食。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年七月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "875aca07-ce04-5e21-9b2d-1bdc87189a6b"}, {"title": "宋琥镇守甘肃", "description": "西宁侯宋琥奉命镇守甘肃。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "94ce8a36-fc76-56c8-9d15-d394979d8a7f"}, {"title": "明廷赈济安庆等地饥荒", "description": "明廷下令赈济安庆、徽州、凤阳和镇江的饥荒。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年七月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf09e978-8c10-59b2-82d5-f2de0bb07fa6"}, {"title": "朱棣回到北京并在奉天殿受贺", "description": "朱棣北征归来，七月壬午抵达北京，在奉天殿接受朝贺。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年七月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2aa6065f-1530-598f-b3ba-0436e0b1be3b"}, {"title": "明廷按北征战功分别行赏", "description": "朝廷根据北征中各人功劳分别给赏。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年七月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3decea79-ade6-5aef-a26b-d85a4894f211"}, {"title": "柳升进封安远侯", "description": "朝廷将柳升进封为安远侯。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年八月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ef9a230-e943-52fa-9ead-9e4967ff8b5f"}, {"title": "何福自杀身亡", "description": "本纪记载，何福在八月乙卯自杀。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年八月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "93b0a2fe-2d4b-54d6-92f4-20b49d328cea"}, {"title": "开封黄河漫溢", "description": "本纪记载，黄河于八月庚申在开封漫溢。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年八月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3199a634-b846-55f0-92c6-7f29b4b633d3"}, {"title": "朱棣到天寿山", "description": "朱棣于九月己巳到天寿山。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年九月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "99fa4623-2acb-578f-bf0f-001e03e0214a"}, {"title": "朱棣离开北京", "description": "朱棣于十月丁酉从北京启程。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年十月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "02be4001-46c4-5645-92c8-9a9aab9815aa"}, {"title": "福州遭倭寇进犯", "description": "本纪记载，倭寇在这个月进犯福州。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bd965692-304b-5fc9-b28e-aa7bd270e5d2"}, {"title": "朱棣回到京师", "description": "朱棣于十一月甲戌回到京师。", "start_year": 1410, "end_year": 1410, "time_original": "永乐八年十一月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4f59b7bd-6913-5be4-bdb3-374aff3ac932"}, {"title": "阿鲁台派使者向明廷贡马", "description": "阿鲁台派出使者进贡马匹。", "start_year": 1411, "end_year": 1411, "time_original": "永乐八年十二月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9087147c-b69f-5e5f-b9e4-0179083de5d4"}, {"title": "陈季扩请降但未接受明廷所授官职", "description": "陈季扩请求归降，朝廷任命他为交阯右布政使，陈季扩没有接受任命。", "start_year": 1411, "end_year": 1411, "time_original": "永乐八年十二月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a5beb00d-9815-5f04-9e34-3fb8edfc5195"}, {"title": "失捏干进犯黄河东岸，王俶战败身亡", "description": "本纪记载，失捏干进犯黄河东岸，宁夏都指挥王俶所部战败，王俶身亡。 按原历纪年，事情发生在公元1410至1411年之间。", "start_year": null, "end_year": null, "time_original": "永乐八年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f610f33a-cdf9-5eea-920a-16479479cead"}, {"title": "浡泥吕宋等地来贡", "description": "本纪记浡泥、吕宋、冯嘉施兰、苏门答剌、榜葛剌入贡，占城贡象，琉球山南、爪哇、暹罗贡马，琉球中山来贡三次。 按原历纪年，事情发生在公元1410至1411年之间。", "start_year": null, "end_year": null, "time_original": "永乐八年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bb4687f0-26ad-583f-8169-70ea877b25b6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

